import { test, expect } from '@playwright/test';

test.describe('ZIP Code Auto-formatting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should auto-format ZIP code as user types', async ({ page }) => {
    // Locate and fill ZIP code field using getByLabel
    const zipField = page.getByLabel('ZIP Code');
    await zipField.fill('1234567');

    // Verify the field has been formatted to 5 digits
    await expect(zipField).toHaveValue('1235');

    // Verify the formatted value is displayed in the input
    const formattedValue = await zipField.inputValue();
    expect(formattedValue).toBe('1235');

    // Verify the field has the correct format
    const regex = /^\d{5}$/;
    expect(regex.test(formattedValue)).toBe(true);

    // Verify the field is still interactive
    await zipField.click();
    await expect(zipField).toBeVisible();
  });

  test('should handle partial ZIP code input and allow further typing', async ({ page }) => {
    // Locate and fill ZIP code field using getByLabel
    const zipField = page.getByLabel('ZIP Code');
    await zipField.fill('123');

    // Verify the field has been formatted to 3 digits
    await expect(zipField).toHaveValue('123');

    // Verify the field is still interactive
    await zipField.click();
    await expect(zipField).toBeVisible();

    // Type more characters
    await zipField.fill('490');

    // Verify the field has been formatted to 6 digits
    await expect(zipField).toHaveValue('123490');

    // Verify the field is still interactive
    await zipField.click();
    await expect(zipField).toBeVisible();

    // Verify the field accepts valid 5-digit ZIP codes
    await zipField.fill('90210');
    await expect(zipField).toHaveValue('90210');
  });
});
